B.acu=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uc744 \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc758 \uc791\uc740 \ud30c\uc77c \ud558\ub098\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.amB=new A.l6("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.acu)
B.acy=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
